    """Gerenates diff message string output

    Args:
        target(str) - file/directory to check diff of
        a_ref(str) - first tag
        (optional) b_ref(str) - second git tag

    Returns:
        string: string of output message with diff info
    """
    import subprocess
    import os

    # Determine the repository root to ensure commands run in correct directory
    try:
        repo_root = subprocess.check_output(
            ["git", "rev-parse", "--show-toplevel"], stderr=subprocess.DEVNULL
        ).decode().strip()
    except subprocess.CalledProcessError:
        return "Error: Not a git repository."

    # Resolve the target path; default to repository root if not provided
    if target:
        target_path = os.path.abspath(target)
        if not os.path.exists(target_path):
            return f"Error: Target path '{target}' does not exist."
    else:
        target_path = repo_root

    # Build the diff reference spec
    if b_ref:
        ref_spec = f"{a_ref}..{b_ref}"
    else:
        ref_spec = a_ref

    # Construct the git diff command
    cmd = ["git", "diff", ref_spec, "--", target_path]

    try:
        diff_output = subprocess.check_output(
            cmd, cwd=repo_root, stderr=subprocess.STDOUT
