def publish(cls, message, client_filter=None):
    """Publish messages to subscribers.

    Args:
      message: The message to publish.
      client_filter: A filter function to call passing in each client. Only
                     clients for whom the function returns True will have the
                     message sent to them.
    """
    # Retrieve the collection of subscriber clients.
    subscribers = getattr(cls, "_subscribers", None)
    if subscribers is None:
        subscribers = getattr(cls, "clients", [])
    # Ensure we have an iterable (convert to list to avoid mutation issues).
    try:
        iterator = list(subscribers)
    except TypeError:
        iterator = []
    # Send the message to each client that passes the optional filter.
    for client in iterator:
        # Apply filter if provided.
        if client_filter is not None:
            try:
                if not client_filter(client):
                    continue
            except Exception:
                continue
        # Attempt to deliver the message using a common sending method.
        for method_name in ("send", "publish", "write", "notify"):
            method = getattr(client, method_name, None)
            if callable(method):
