            self.time = 0
        self.time += 1

        _resolve = getattr(self, "_resolve_pending", None)
        if callable(_resolve):
            _resolve()

        _events = getattr(self, "_scheduled_events", None)
        if isinstance(_events, dict):
            for fn in _events.pop(self.time, []):
                fn()

        return getattr(self, "state", None)

