def LoadFromXml(self, node, handle):
		"""	Method updates/fills the object from the xml representation of the managed object. """
        # Populate attributes from XML node attributes
        for attr_name, attr_value in node.attrib.items():
            setattr(self, attr_name, attr_value)

        # Populate attributes from child elements
        for child in node:
            tag = child.tag
            # If the child has its own children, delegate to the provided handler
            if list(child):
                try:
                    value = handle(child)
                except Exception:
                    # Fallback: store the raw Element if handler fails
                    value = child
            else:
                # Use text content; strip whitespace, treat empty as None
                text = child.text.strip() if child.text else None
                value = text

            # Assign the derived value to an attribute named after the tag
            setattr(self, tag, value)

